class TreeNode {
    int wartosc;
    TreeNode lewe, prawe;
    TreeNode(int w) { wartosc = w; }
}

void inorder(TreeNode wezel, List<Integer> wynik) {
    if (wezel == null) return; // PRZYPADEK BAZOWY
    inorder(wezel.lewe, wynik);   // najpierw CALE lewe poddrzewo
    wynik.add(wezel.wartosc);      // potem biezacy wezel
    inorder(wezel.prawe, wynik);  // na koncu CALE prawe poddrzewo
}
// dla drzewa z VISUAL_EXAMPLE: [1,3,4,6,7,8,10,13,14] - POSORTOWANE!

TreeNode szukajWBst(TreeNode wezel, int cel) {
    if (wezel == null || wezel.wartosc == cel) return wezel; // znaleziono albo brak
    if (cel < wezel.wartosc) {
        return szukajWBst(wezel.lewe, cel);  // jak 'hi = mid - 1'
    } else {
        return szukajWBst(wezel.prawe, cel); // jak 'lo = mid + 1'
    }
}

TreeNode wstaw(TreeNode wezel, int wartosc) {
    if (wezel == null) return new TreeNode(wartosc);
    if (wartosc < wezel.wartosc) wezel.lewe = wstaw(wezel.lewe, wartosc);
    else wezel.prawe = wstaw(wezel.prawe, wartosc);
    return wezel;
}
// wstaw(1); wstaw(2); wstaw(3); wstaw(4); wstaw(5);
// wynik: 1 -> 2 -> 3 -> 4 -> 5, WSZYSTKIE w prawo - to LISTA, nie zbalansowane drzewo!

TreeSet<Integer> zbalansowane = new TreeSet<>();
for (int i = 1; i <= 5; i++) zbalansowane.add(i); // ta sama kolejnosc co wyzej
// ale TreeSet AUTOMATYCZNIE balansuje - gwarantowane O(log n), nie O(n)

