void preorder(TreeNode w, List<Integer> wynik) {
    if (w == null) return;
    wynik.add(w.wartosc);
    preorder(w.lewe, wynik);
    preorder(w.prawe, wynik);
}

void postorder(TreeNode w, List<Integer> wynik) {
    if (w == null) return;
    postorder(w.lewe, wynik);
    postorder(w.prawe, wynik);
    wynik.add(w.wartosc);
}

int wysokosc(TreeNode w) {
    if (w == null) return -1;
    return 1 + Math.max(wysokosc(w.lewe), wysokosc(w.prawe));
}

TreeNode szukajWBst(TreeNode w, int cel) {
    if (w == null || w.wartosc == cel) return w;
    return cel < w.wartosc ? szukajWBst(w.lewe, cel) : szukajWBst(w.prawe, cel);
}

boolean jestBst(TreeNode w) {
    if (w == null) return true;
    if (w.lewe != null && w.lewe.wartosc >= w.wartosc) return false;
    if (w.prawe != null && w.prawe.wartosc <= w.wartosc) return false;
    return jestBst(w.lewe) && jestBst(w.prawe);
}

TreeNode lca(TreeNode w, int a, int b) {
    if (a < w.wartosc && b < w.wartosc) return lca(w.lewe, a, b);
    if (a > w.wartosc && b > w.wartosc) return lca(w.prawe, a, b);
    return w;   // wartości rozchodzą się albo jedna z nich to w
}

int sumaLisci(TreeNode w) {
    if (w == null) return 0;
    if (w.lewe == null && w.prawe == null) return w.wartosc;
    return sumaLisci(w.lewe) + sumaLisci(w.prawe);
}

boolean maSumeSciezki(TreeNode w, int cel) {
    if (w == null) return false;
    if (w.lewe == null && w.prawe == null) return cel == w.wartosc;
    return maSumeSciezki(w.lewe, cel - w.wartosc)
        || maSumeSciezki(w.prawe, cel - w.wartosc);
}

TreeNode odwroc(TreeNode w) {
    if (w == null) return null;
    TreeNode tmp = w.lewe;
    w.lewe = odwroc(w.prawe);
    w.prawe = odwroc(tmp);
    return w;
}
